const queryAnimeActivity = `-- name: QueryAnimeActivity :many

SELECT
    e.id,
    e.user_id,
    u.username,
    u.avatar_url,
    backdrop.cover_image_url AS backdrop_cover_url,
    COALESCE(e.status, '')::text AS status,
    e.created_at,
    (SELECT count(*)
     FROM activity_likes l
     WHERE l.activity_event_id = e.id)::bigint AS like_count,
    (CASE
        WHEN $1::uuid IS NULL THEN false
        ELSE EXISTS (
            SELECT 1
            FROM activity_likes l
            WHERE l.activity_event_id = e.id
              AND l.user_id = $1::uuid
        )
    END)::boolean AS viewer_liked,
    (SELECT count(*)
     FROM community_replies reply
     WHERE reply.activity_event_id = e.id
       AND reply.deleted_at IS NULL
       AND (
           $1::uuid IS NULL
           OR NOT EXISTS (
               SELECT 1
               FROM user_blocks block
               WHERE (block.blocker_id = $1::uuid AND block.blocked_id = reply.user_id)
                  OR (block.blocker_id = reply.user_id AND block.blocked_id = $1::uuid)
           )
       ))::bigint AS reply_count
FROM activity_events e
JOIN users u ON u.id = e.user_id
LEFT JOIN anime_cache backdrop ON backdrop.anilist_id = u.backdrop_anilist_id
WHERE e.anilist_id = $2::integer
  AND e.event_type = 'status'
  AND ($3::uuid IS NULL OR e.id = $3::uuid)
  AND (u.is_public OR e.user_id = $1::uuid)
  AND (
      $1::uuid IS NULL
      OR NOT EXISTS (
          SELECT 1
          FROM user_blocks block
          WHERE (block.blocker_id = $1::uuid AND block.blocked_id = e.user_id)
             OR (block.blocker_id = e.user_id AND block.blocked_id = $1::uuid)
      )
  )
ORDER BY e.created_at DESC, e.id DESC
LIMIT $5::integer
OFFSET $4::integer
`

