const removeActivityLike = `-- name: RemoveActivityLike :one
WITH deleted AS (
    DELETE FROM activity_likes
    WHERE activity_event_id = $1::uuid
      AND user_id = $2::uuid
    RETURNING activity_event_id
)
SELECT greatest(
    (SELECT count(*) FROM activity_likes WHERE activity_event_id = $1::uuid)
    - (SELECT count(*) FROM deleted),
    0
)::bigint AS like_count
`

func (q *Queries) RemoveActivityLike(ctx context.Context, eventID uuid.UUID, userID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, removeActivityLike, eventID, userID)
	var like_count int64
	err := row.Scan(&like_count)
	return like_count, err
}

