const softDeleteAnimeReview = `-- name: SoftDeleteAnimeReview :execrows
UPDATE anime_reviews
SET deleted_at = now(),
    deleted_by = $1::uuid,
    updated_at = now()
WHERE id = $2::uuid
  AND deleted_at IS NULL
`

// The author's delete and an admin's removal are the same write; deleted_by
// records which.  Already-deleted rows are left alone (0 rows).
func (q *Queries) SoftDeleteAnimeReview(ctx context.Context, actorID uuid.UUID, reviewID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteAnimeReview, actorID, reviewID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const softDeleteAnimeThread = `-- name: SoftDeleteAnimeThread :one
WITH deleted AS (
    UPDATE anime_threads
    SET deleted_at = now(),
        deleted_by = $1::uuid,
        updated_at = now()
    WHERE id = $2::uuid
      AND deleted_at IS NULL
    RETURNING id
), removed_notifications AS (
    DELETE FROM notifications notification
    USING community_replies reply, deleted
    WHERE notification.reply_id = reply.id
      AND reply.thread_id = deleted.id
    RETURNING notification.id
)
SELECT count(*)::bigint AS deleted FROM deleted
`

// Removing a thread also removes the notifications its replies sent: an
// inbox must not link into a thread that answers 404.  The replies
// themselves stay as they are, unreachable behind the deleted thread.
func (q *Queries) SoftDeleteAnimeThread(ctx context.Context, actorID uuid.UUID, threadID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, softDeleteAnimeThread, actorID, threadID)
	var deleted int64
	err := row.Scan(&deleted)
	return deleted, err
}

const softDeleteCommunityReply = `-- name: SoftDeleteCommunityReply :one
WITH deleted AS (
    UPDATE community_replies
    SET deleted_at = now(),
        deleted_by = $1::uuid,
        updated_at = now()
    WHERE id = $2::uuid
      AND deleted_at IS NULL
    RETURNING id
), removed_notifications AS (
    DELETE FROM notifications notification
    USING deleted
    WHERE notification.reply_id = deleted.id
    RETURNING notification.id
)
SELECT count(*)::bigint AS deleted FROM deleted
`

// The reply's notifications go in the same statement, so an inbox never
// quotes a reply its author took back.
func (q *Queries) SoftDeleteCommunityReply(ctx context.Context, actorID uuid.UUID, replyID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, softDeleteCommunityReply, actorID, replyID)
	var deleted int64
	err := row.Scan(&deleted)
	return deleted, err
}

const updateAnimeReview = `-- name: UpdateAnimeReview :one
UPDATE anime_reviews
SET summary    = $1::text,
    body       = $2::text,
    is_spoiler = $3::boolean,
    is_private = $4::boolean,
    updated_at = now()
WHERE id = $5::uuid
  AND user_id = $6::uuid
  AND deleted_at IS NULL
RETURNING id
`

type UpdateAnimeReviewParams struct {
	Summary   string    `json:"summary"`
	Body      string    `json:"body"`
	IsSpoiler bool      `json:"isSpoiler"`
	IsPrivate bool      `json:"isPrivate"`
	ReviewID  uuid.UUID `json:"reviewId"`
	UserID    uuid.UUID `json:"userId"`
}

// Author-only, enforced here as well as by the handler: a request for
// someone else's review matches no row.
func (q *Queries) UpdateAnimeReview(ctx context.Context, arg UpdateAnimeReviewParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, updateAnimeReview,
		arg.Summary,
		arg.Body,
		arg.IsSpoiler,
		arg.IsPrivate,
		arg.ReviewID,
		arg.UserID,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}
